function metricGlyph(i){const paths=['<path d="M20 11a7 7 0 0 1-7 7H6l-4 3 1-6a7 7 0 0 1-1-4 7 7 0 0 1 7-7h4a7 7 0 0 1 7 7Z"/><path d="M7 9h8M7 13h5"/>','<circle cx="8" cy="7" r="3"/><path d="M2 20v-2a6 6 0 0 1 9-5"/><circle cx="17" cy="16" r="6"/><path d="M17 12v8m2-6h-3a1.5 1.5 0 0 0 0 3h2a1.5 1.5 0 0 1 0 3h-3"/>','<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M5 9h1m12 6h1M5 15h1m12-6h1"/>','<path d="M4 10a8 8 0 1 1 0 5M4 4v6h6"/>'];const c=[0,1,5,4][i];return '<div class="glyph" style="--color:'+colors[c]+';--tint:'+tints[c]+'"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[i]+'</svg></div>'}

const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons=['♕','♧','◎','▱','↗','$','♧','♙','✧'],colors=['#3477ec','#8747ed','#00aa82','#f27927','#e8a500','#0bac69','#7770ed','#e4509b','#9b64e8'],tints=['#e1edff','#eee8ff','#d8faeb','#ffead6','#fff4cc','#dcffeb','#e8e9ff','#fce5f2','#f0e7ff'];
const names=['Leadership','People & Culture','Talent & Hiring','Difficult Conversations','Scale & Growth Strategy','Financial Strategy','Innovation & Product','Sales & Marketing','Strategic Planning','Executive Coaching'];
const tags=['Build executive presence and lead with confidence','Create thriving team environments','Attract and retain top talent','Navigate challenging discussions with ease','Scale your business to the next level','Master business finances and profitability','Build products customers love','Generate leads and close deals','Create winning business strategies','1-on-1 personalized guidance'];
const desc=['Develop your leadership skills, build executive presence, and learn how to inspire and guide your team effectively.','Foster a positive workplace culture, improve team dynamics, and create an environment where people thrive.','Master the art of recruiting, interviewing, and retaining the best talent for your organization.','Handle tough conversations with confidence, from performance reviews to conflict resolution and feedback delivery.','Strategic frameworks for sustainable growth, market expansion, and scaling operations while maintaining quality and culture.','Advanced financial planning, cash flow management, and building a sustainable business model.','Product strategy, innovation frameworks, customer discovery, and launching new offerings that drive business growth.','Master sales techniques, marketing strategies, and building a predictable revenue pipeline.','Long-term strategic planning, competitive analysis, and executing strategic initiatives.','Personalized guidance with tailored insights and advanced capabilities.'];
const initial={agents:names.map((name,i)=>({name,tag:tags[i],desc:desc[i],icon:i%9,favorite:false,tier:i===9?'Premium':'Free'})),qa:[{question:'What makes a great leader?',answer:'Great leaders combine vision, empathy, and decisiveness. They inspire their teams through clear communication, lead by example, and create an environment where people feel valued and empowered to contribute their best work.',category:'Leadership Basics',agent:0},{question:'How do I handle a difficult employee?',answer:'Address the issue promptly and privately. Focus on specific behaviors rather than personality. Listen to their perspective, clearly communicate expectations, and agree on concrete next steps with timelines. Document the conversation and follow up regularly.',category:'Management',agent:0},{question:'What are the key metrics for team performance?',answer:'Choose metrics that align with your team objectives: productivity, quality, engagement, efficiency, and goal achievement. Review the results with your team regularly.',category:'Performance',agent:0}],files:[{name:'Leadership Fundamentals Guide',type:'Document',size:'2.4 MB',agent:0},{name:'Executive Presence Masterclass',type:'Video',size:'145 MB',agent:0},{name:'Team Building Best Practices',type:'Document',size:'1.8 MB',agent:0},{name:'Harvard Business Review Articles',type:'Link',size:'External link',agent:0},{name:'Performance Review Templates',type:'Document',size:'890 KB',agent:0}],pending:[{question:'How do I transition from manager to executive?',users:3,agent:0},{question:'Dealing with board member conflicts',users:2,agent:0},{question:'Leading through a company merger',users:1,agent:0}],plan:'Professional',profile:{name:'Emily Johnson',email:'emily@coachingbusiness.com'},drafts:[]};
let db;try{db=JSON.parse(localStorage.getItem('xpertloop-new-v1'))||structuredClone(initial)}catch{db=structuredClone(initial)}
let dashboardPeriod='current';
let route='home',agentId=0,tab='chat',contentTab='files',dashAgent=0,messages={},draft={},step=1,uploadType='Document',chosenFiles=[],generated='',toastTimer;
function save(){try{localStorage.setItem('xpertloop-new-v1',JSON.stringify(db))}catch{toast('Browser storage is full. Your changes remain in this session.')}}
function glyph(i){return `<div class="glyph" style="--color:${colors[i%9]};--tint:${tints[i%9]}">${icons[i%9]}</div>`}
function toast(t){$('#toast').textContent='✓  '+t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function go(r){location.hash=r}function openAgent(i){agentId=i;tab='chat';go('agent-'+i);if(route==='agent-'+i)render()}
function nav(){ const sidebar=document.querySelector('aside');if(sidebar){const section=route.startsWith('agent-')?'agents':route;sidebar.dataset.section=section;const positions={agents:['0%','15%'],dashboard:['75%','45%'],create:['100%','95%']};const pos=positions[section]||['35%','55%'];sidebar.style.setProperty('--sidebar-x',pos[0]);sidebar.style.setProperty('--sidebar-y',pos[1]);}$('#nav').innerHTML=[["agents","<svg width=\"21\" height=\"21\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"5\" y=\"7\" width=\"14\" height=\"13\" rx=\"3\"/><path d=\"M12 3v4M2 12v4m20-4v4M9 16h6\"/><circle cx=\"9\" cy=\"12\" r=\".75\" fill=\"currentColor\"/><circle cx=\"15\" cy=\"12\" r=\".75\" fill=\"currentColor\"/><circle cx=\"12\" cy=\"3\" r=\"1\" fill=\"currentColor\"/></svg>","Agents"],["dashboard","<svg width=\"21\" height=\"21\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 3v17h17M8 16v-4m5 4V8m5 8V5\"/></svg>","Dashboard"],["create","<svg width=\"21\" height=\"21\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z\"/><path d=\"M14 2v6h6M8 12h8M8 16h6\"/></svg>","Content Studio"]].map(([r,i,n])=>`<button onclick="go('${r}')" class="${route===r||r==='agents'&&route.startsWith('agent-')?'active':''}" title="${n}"><span>${i}</span>${n}</button>`).join('')}
function render(){route=location.hash.slice(1)||'dashboard';if(route==='home')route='dashboard';if(route.startsWith('agent-')){agentId=Number(route.split('-')[1]);if(!db.agents[agentId]){go('agents');return}}nav();const titles={home:'Home',agents:'Agents',dashboard:'Dashboard',create:'Content studio',billing:'Billing & Plans',plans:'Change plan',profile:'Profile settings',account:'Account settings',notifications:'Notifications',support:'Help & support'};$('#crumb').innerHTML=route.startsWith('agent-')?`<a href="#agents">Agents</a><span>/</span><strong>${esc(db.agents[agentId].name)}${agentId===0?' Coach':''}</strong>`:route==='usage'?'<a href="#account">Account</a><span>/</span><strong>Usage</strong>':route==='billing'?'<a href="#account">Account</a><span>/</span><strong>Billing &amp; Plans</strong>':route==='plans'?'<a href="#account">Account</a><span>/</span><a href="#billing">Billing &amp; Plans</a><span>/</span><strong>Change plan</strong>':'';let html=route==='home'?home():route==='agents'?agents():route==='dashboard'?dashboard():route.startsWith('agent-')?agent():route==='create'?studio():route==='usage'?usagePage():route==='billing'?billing():route==='plans'?plans():settings(route);$('#app').innerHTML='<div class="page">'+html+'</div>';animateNumbers()}
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0)});
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`}
const stats=[['Total Sessions','1,004','+220 from last month','↑ 28.12%',0],['Active Paying Clients','193','−2 from last month','↓ 1.03%',1],['Monthly Revenue','$5,200','+$210 from last month','↑ 4.2%',5],['Return Rate','72%','+5% from last month','↑ 7.46%',4]];
function metrics(simple=false){return `<div class="grid four metrics">${stats.map((s,i)=>`<button class="card metric" onclick="metricDetail(${i})"><div class="metric-top">${metricGlyph(i)}<span class="badge">↗</span></div><small>${s[0]}</small><div class="number" data-count="${s[1]}">${s[1]}</div><div class="change"><span>${s[2]}</span><b class="${s[3].startsWith('↓')?'red':'green'}">${s[3]}</b></div></button>`).join('')}</div>`}
function home(){return `<div class="hero"><h1>Good morning, Emily <span style="font-size:27px">☀</span></h1><p>Your knowledge is making an impact. What would you like to do today?</p></div><div class="grid two home-actions"><div class="card" role="button" tabindex="0" onclick="go('agents')" onkeydown="if(event.key==='Enter')go('agents')"><span class="arrow">↗</span>${homeActionIcon(0)}<h2>See my agents</h2><p>Give your clients guidance that sounds like you. Manage your agents and see the difference they're making.</p><small><span class="status">${db.agents.filter(a=>!a.paused).length} ${db.agents.filter(a=>!a.paused).length===1?'agent active':'agents active'}</span></small></div><div class="card" role="button" tabindex="0" onclick="go('create')" onkeydown="if(event.key==='Enter')go('create')"><span class="arrow">↗</span>${homeActionIcon(1)}<h2>Create content</h2><p>Turn your expertise and your audience's questions into content worth sharing. All in your voice.</p><small>LinkedIn, Instagram, X &nbsp; · &nbsp; AI-assisted</small></div></div><div class="section-title"><h2>Your impact at a glance</h2><button class="text-button" onclick="go('dashboard')">View dashboard ↗</button></div>${metrics()}<div class="card"><div class="page-heading" style="margin:0"><div><span class="status">Knowledge opportunity</span><h3 style="margin:10px 0 5px">Your clients are asking. You have the answers.</h3><p style="font-size:12px;margin:0">${db.pending.length} questions are waiting for your expertise.</p></div><button class="secondary" onclick="agentId=0;tab='analytics';go('agent-0')">Review questions →</button></div></div>`}
function agents(){return heading('Your agents','A little more of you. A lot more possibility.',`<button class="primary" onclick="newAgent()">＋ Add new agent</button>`)+`<div class="page-heading"><span class="badge">${db.agents.length} agents in your workspace</span><input style="width:230px;padding:9px 12px" placeholder="Search agents…" aria-label="Search agents" oninput="filterAgents(this.value)"></div><div class="grid two" id="agent-grid">${agentCards()}</div>`}
function agentCards(filter=''){return db.agents.map((a,i)=>({...a,id:i})).filter(a=>(a.name+' '+a.tag).toLowerCase().includes(filter.toLowerCase())).map(a=>`<article class="card agent-card"><button class="favorite ${a.favorite?'on':''}" aria-label="${a.favorite?'Remove favorite':'Favorite agent'}" onclick="favorite(${a.id},this)">${a.favorite?'★':'☆'}</button>${glyph(a.icon)}<h3>${esc(a.name)} <span style="font-weight:400;color:#aeb6c2">/</span> ${esc(a.tag)}</h3><p>${esc(a.desc)}</p><div class="card-footer"><button class="secondary" onclick="openAgent(${a.id})">Open agent →</button><span class="status">Active</span></div></article>`).join('')||'<p>No agents match your search.</p>'}
function filterAgents(v){$('#agent-grid').innerHTML=agentCards(v)}function favorite(i,b){db.agents[i].favorite=!db.agents[i].favorite;b.classList.toggle('on');b.textContent=db.agents[i].favorite?'★':'☆';save()}
function lineChart(values=[45,52,48,51,47,50,49],labels=['Jan 7','Jan 8','Jan 9','Jan 10','Jan 11','Jan 12','Jan 13'],color='#008ac7',money=false){let max=Math.max(...values)*1.2;let pts=values.map((v,i)=>[45+i*650/(values.length-1),195-v/max*165]);return `<svg class="chart" viewBox="0 0 730 230" role="img" aria-label="${money?'Revenue':'Session'} trend">${[0,1,2,3].map(i=>`<line x1="45" y1="${30+i*55}" x2="695" y2="${30+i*55}" stroke="#e8edf3" stroke-dasharray="4 4"/><text x="3" y="${34+i*55}">${money?'$':''}${Math.round(max*(1-i/3))}</text>`).join('')}${money?`<polygon points="45,195 ${pts.map(p=>p.join(',')).join(' ')} 695,195" fill="${color}" opacity=".08"/>`:''}<polyline class="draw" points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="${color}"><title>${labels[i]}: ${money?'$':''}${values[i]}</title></circle><text x="${p[0]}" y="220" text-anchor="middle">${labels[i]}</text>`).join('')}</svg>`}
function dashboard(){applyDashboardPeriod();return heading('Your business, in focus','A clear picture of your impact, across every agent.',`<div class="dashboard-period"><label for="dashboard-period">Month</label><select id="dashboard-period" onchange="dashboardPeriod=this.value;render()"><option value="current" ${dashboardPeriod==='current'?'selected':''}>November 2026</option><option value="previous" ${dashboardPeriod==='previous'?'selected':''}>October 2026</option></select></div>`)+metrics()+`<div class="grid two"><div class="card"><h2>Revenue</h2><p style="font-size:11px">Six months of growing your impact</p>${lineChart(dashboardPeriod==='current'?[2400,3100,3800,4200,4990,5200]:[2100,2400,3100,3800,4200,4990],dashboardPeriod==='current'?['Jun','Jul','Aug','Sep','Oct','Nov']:['May','Jun','Jul','Aug','Sep','Oct'],'#0ab88b',true)}</div><div class="card"><h2>Agent performance</h2><p style="font-size:11px">Sessions by agent · ${dashboardPeriod==='current'?'November':'October'}</p><div class="donut-layout"><div class="donut" style="${dashboardPeriod==='previous'?'background:conic-gradient(#92c4ff 0 34.44%,#a58cf5 34.44% 60.59%,#efa4cf 60.59% 82.91%,#ffdb65 82.91%)':''}" role="img" aria-label="Sessions by agent"></div><div class="legend"><div><b style="font-size:25px">${dashboardPeriod==='current'?'1,004':'784'}</b><small>total sessions</small></div>${(dashboardPeriod==='current'?[342,267,219,176]:[270,205,175,134]).map((v,i)=>`<div><span><i class="dot" style="background:${['#92c4ff','#a58cf5','#efa4cf','#ffdb65'][i]}"></i>${names[i]}</span><b>${v}</b></div>`).join('')}</div></div></div></div><section class="dashboard-questions" id="dashboard-questions">${dashboardQuestions()}</section>`}
function topQuestions(i){const name=db.agents[i]?.name||'this topic';const base=i===0?['How can I improve my executive presence?','What are effective leadership communication strategies?','How do I handle team conflicts?','How do I delegate effectively?','How can I motivate an underperforming team?']:i===1?['How can I improve my people & culture skills?','How do I build psychological safety on my team?','What should I cover in a one-on-one?','How can I create a culture of feedback?','How do I recognize people fairly?']:[`How can I improve my ${name.toLowerCase()} skills?`,`Where should I start with ${name.toLowerCase()}?`,'What practical steps can I take this week?','How can I measure my progress?','What common mistakes should I avoid?'];return [...base,'How do I turn these principles into a daily habit?','How can I get my team involved?','What should I focus on over the next month?']}

function agent(){let a=db.agents[agentId];return `<div class="agent-heading"><div class="agent-title"><div class="agent-title-row"><h2>${esc(a.name)}${agentId===0?' Coach':''}</h2><span class="status ${a.paused?'paused':''}">${a.paused?'Paused':'Active'}</span></div><p>${esc(a.description||a.tag)}</p></div><div class="tabs">${['chat','analytics','content'].map(t=>`<button class="${tab===t?'selected':''}" onclick="tab='${t}';render()">${{"chat":"<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-3 2 2-6a8.5 8.5 0 1 1 18-4.5Z\"/></svg> Chat","analytics":"<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 3v17h17M8 16v-4m5 4V8m5 8V5\"/></svg> Analytics","content":"<svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15\"/></svg> Content"}[t]}</button>`).join('')}</div><button class="outline edit-agent" onclick="editAgentModal()">Edit agent</button></div>${tab==='chat'?chat():tab==='analytics'?analytics():content()}`}
function chat(){let a=db.agents[agentId],m=messages[agentId]||[];return `<div class="chat"><div class="chat-messages" id="messages"><div class="message"><div class="bubble">Hi ${esc((db.profile.name||'Emily').trim().split(/\s+/)[0])}! I'm your ${esc(a.name.toLowerCase())} coach, here to help you ${esc(a.tag.toLowerCase().replace(/[.!?]+$/,''))}.<br>What’s on your mind today?</div></div>${m.map(x=>`<div class="message ${x.role}"><div class="bubble">${esc(x.text)}</div></div>`).join('')}</div>${!m.length?`<div class="suggestions"><p style="font-size:11px">✧ A few places to start</p><div class="grid two">${topQuestions(agentId).slice(0,4).map(q=>`<button onclick="animateStarter(${esc(JSON.stringify(q))},this)">${q}</button>`).join('')}</div></div>`:''}<form class="composer" onsubmit="event.preventDefault();sendChat()"><textarea rows="1" id="chat-input" placeholder="Ask your coach anything…" aria-label="Message your agent" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendChat()}"></textarea><button class="primary" type="submit">Send ↗</button></form><p class="demo-note">Prototype responses · Uses your saved Q&A · Enter to send</p></div>`}
function sendChat(text){text=(text||$('#chat-input').value).trim();if(!text)return;if(db.agents[agentId].paused){toast('This agent is paused. Resume it in Edit agent to test a conversation.');return}const id=agentId;messages[id]??=[];messages[id].push({role:'user',text});render();$('#messages').insertAdjacentHTML('beforeend','<div class="message" id="thinking"><div class="bubble thinking"><i></i><i></i><i></i></div></div>');const qa=db.qa.filter(q=>q.agent===id);const words=s=>s.toLowerCase().match(/[a-z]{4,}/g)||[];let best,score=0;qa.forEach(q=>{let exact=q.question.toLowerCase()===text.toLowerCase(),n=words(text).filter(w=>words(q.question).includes(w)).length;if(exact||n>score){score=exact?999:n;best=q}});let answer;if(best&&score>0)answer=best.answer;else if(/executive presence|communication|delegat|conflict|leader/.test(text.toLowerCase())&&id===0)answer='Start with one specific situation you want to improve. Before your next meeting, write down the outcome you want and the one message your team should remember. Communicate that message clearly, invite a different perspective, and agree on a concrete next step.\n\nWhat is the situation you have in mind?';else{answer="I don't have enough of this expert's knowledge on that topic yet. I've flagged your question so they can add their perspective. Try asking about a saved Q&A topic, or add an answer in Analytics and ask me again.";if(!db.pending.some(q=>q.question.toLowerCase()===text.toLowerCase()&&q.agent===id)){db.pending.push({question:text,users:1,agent:id});save()}}setTimeout(()=>{messages[id].push({role:'assistant',text:answer});if(route==='agent-'+id&&tab==='chat'){render();$('#chat-input').focus();$('#messages').lastElementChild?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}},1000)}
function analytics(){const previous=dashboardPeriod==='previous',month=previous?'October 2026':'November 2026';const rows=previous?[['Total Sessions','270','−10%',0],['Active Users','144','+5%',1],['Avg. Session Time','8.4m','+4%',2],['Satisfaction','93%','+2%',3]]:[['Total Sessions','342','+27%',0],['Active Users','156','+8%',1],['Avg. Session Time','9.2m','+10%',2],['Satisfaction','96%','+3%',3]];return `<div class="analytics-overview-heading"><h2>Performance overview</h2><div class="dashboard-period"><label for="analytics-period">Month</label><select id="analytics-period" onchange="dashboardPeriod=this.value;render()"><option value="current" ${!previous?'selected':''}>November 2026</option><option value="previous" ${previous?'selected':''}>October 2026</option></select></div></div><div class="grid four metrics">${rows.map((x,i)=>`<div class="card"><div style="display:flex;gap:14px;align-items:center">${performanceGlyph(i)}<div><small>${x[0]}</small><div class="number" style="margin:5px 0">${x[1]}</div></div></div><small class="${x[2].startsWith('−')?'red':'green'}" style="display:block;margin-top:15px">${x[2]} from previous month</small></div>`).join('')}</div><div class="card"><div class="insight-panel-heading" style="padding:0 0 20px"><h2>Session trends</h2><span class="badge">${month}</span></div>${lineChart(previous?[49,43,54,62,62]:[62,74,69,72,65],previous?['Oct 1–6','Oct 7–12','Oct 13–18','Oct 19–24','Oct 25–31']:['Nov 1–6','Nov 7–12','Nov 13–18','Nov 19–24','Nov 25–30'])}</div><div class="grid two insights-grid" style="margin-top:24px">${agentQuestionPanels(agentId,true)}</div>` }

function content(){let files=db.files.filter(f=>f.agent===agentId),qa=db.qa.filter(q=>q.agent===agentId);return heading('Training content library',contentTab==='files'?"A home for the knowledge that makes your agent yours.":'Train your agent with your perspective, one answer at a time.',`<div style="display:flex;gap:12px"><div class="tabs"><button class="${contentTab==='files'?'selected':''}" onclick="contentTab='files';render()">Files</button><button class="${contentTab==='qa'?'selected':''}" onclick="contentTab='qa';render()">Q&A</button></div><button class="primary" onclick="${contentTab==='files'?'uploadModal()':'qaModal()'}">＋ ${contentTab==='files'?'Upload content':'Add Q&A'}</button></div>`)+(contentTab==='files'?`<div class="grid four metrics">${['Document','Video','Link','Total items'].map((t,i)=>`<div class="card"><small>${['▤','▹','↗','↑'][i]} &nbsp;${t==='Document'?'Documents':t==='Video'?'Videos':t==='Link'?'Links':t}</small><div class="number" style="margin-bottom:0">${i===3?files.length:files.filter(f=>f.type===t).length}</div></div>`).join('')}</div><div class="card content-list"><h3 class="list-title">All content (${files.length})</h3>${files.map(f=>`<div class="file-row"><span class="file-type-label">${fileTypeLabel(f)}</span><div><h3>${esc(f.name)}</h3><small>${esc(f.size)} &nbsp; · &nbsp; Uploaded by you</small></div><button aria-label="Remove content" class="close" onclick="removeFile(${db.files.indexOf(f)})">×</button></div>`).join('')||'<div class="empty"><h3>Your knowledge starts here</h3><p>Upload your first resource to get started.</p><button class="primary" onclick="uploadModal()">Upload content</button></div>'}</div><p class="demo-note">Demo library: file names are saved locally. Files are not processed or uploaded to an AI service.</p>`:`<div class="card content-list"><h3 class="list-title">All Q&A pairs (${qa.length})</h3>${qa.map(q=>`<div class="qa-row"><span class="badge">${esc(q.category||'General')}</span><h3>${esc(q.question)}</h3><p>${esc(q.answer)}</p><small>Added to your agent's knowledge</small><button style="float:right" class="text-button" onclick="qaModal(${db.qa.indexOf(q)})">Edit answer</button></div>`).join('')||'<div class="empty"><h3>Make it sound like you</h3><p>Add a question your clients ask and answer it in your own words.</p><button class="primary" onclick="qaModal()">＋ Add Q&A</button></div>'}</div>`)}
function removeFile(i){modal('Remove resource',`<p>Remove <b>${esc(db.files[i].name)}</b> from this agent's library?</p>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" onclick="db.files.splice(${i},1);save();closeModal();render();toast('Resource removed')">Remove</button>`)}
function modal(title,body,footer=''){ $('#overlay').innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title.replace(/<[^>]*>/g,''))}"><div class="modal-head"><h2>${title}</h2><button class="close" aria-label="Close dialog" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section>`;$('#overlay').onclick=e=>{if(e.target.id==='overlay')closeModal()};setTimeout(()=>$('.modal input,.modal textarea,.modal button')?.focus(),40)}
let previousFocus;function closeModal(){ closeAccountMenu();$('#overlay').innerHTML='';previousFocus?.focus() }document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){let nodes=[...$('.modal').querySelectorAll('button,input,textarea,select,a')].filter(n=>!n.disabled&&n.offsetParent);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0]?.focus()}}});
function qaModal(edit=-1,pending=-1){previousFocus=document.activeElement;let q=edit>=0?db.qa[edit]:pending>=0?{question:db.pending[pending].question}:{};modal(pending>=0?'Share your expertise':edit>=0?'Edit Q&A':'Add a Q&A pair',`<p style="font-size:12px">Your answer becomes part of your agent's knowledge.</p><form id="qa-form" onsubmit="event.preventDefault();saveQa(${edit},${pending})"><div class="form-group"><label for="q-question">Question *</label><input id="q-question" required value="${esc(q.question||'')}" placeholder="What do your clients want to know?"></div><div class="form-group"><label for="q-answer">Your answer *</label><textarea class="field" id="q-answer" rows="6" required placeholder="Share your approach, in your own words…">${esc(q.answer||'')}</textarea></div><div class="form-group"><label for="q-category">Category</label><input id="q-category" value="${esc(q.category||'')}" placeholder="e.g. Leadership Basics"></div></form>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" type="submit" form="qa-form">Save to agent ✧</button>`)}
function answerQuestion(i){agentId=db.pending[i].agent;qaModal(-1,i)}function saveQa(edit,pending){const q={question:$('#q-question').value.trim(),answer:$('#q-answer').value.trim(),category:$('#q-category').value.trim()||'General',agent:agentId};if(!q.question||!q.answer)return;if(edit>=0)db.qa[edit]=q;else db.qa.push(q);if(pending>=0)db.pending.splice(pending,1);save();closeModal();render();toast(pending>=0?'Knowledge gap filled. Try this question in Chat.':'Q&A saved to your agent')}
function newAgent(){draft={name:'',tag:'',description:'',group:'',newGroupName:'',files:[],tier:'Free',icon:0,tone:'Warm & encouraging',instructions:''};step=1;agentWizard()}
function readAgentDraft(){if(step===1){draft.name=$('#a-name').value.trim();draft.description=$('#a-description').value.trim();draft.tag=draft.description;draft.group=$('#a-group').value;draft.newGroupName=$('#a-group-name').value.trim()}else if(step===2){draft.tone=$('#a-tone').value;draft.instructions=draft.instructions||''}}

function agentWizard(){const body=step===1?`<h3>Tell us about your agent</h3><p style="font-size:12px">Give it a clear name and describe how it will help your clients.</p><form id="agent-form" onsubmit="event.preventDefault();advanceAgent()"><div class="form-group"><label for="a-name">Agent name *</label><input id="a-name" required value="${esc(draft.name)}" placeholder="e.g. Difficult Conversations"></div><div class="form-group"><label for="a-description">Description *</label><textarea class="field" id="a-description" required rows="3" placeholder="What will this agent help people with?">${esc(draft.description||'')}</textarea></div><div class="form-group"><label for="a-group">Group <small>· Optional</small></label><select id="a-group" onchange="$('#new-group-field').hidden=this.value!=='__new'" ><option value="">Ungrouped</option>${db.groups.map(g=>`<option value="${esc(g.id)}" ${draft.group===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}<option value="__new" ${draft.group==='__new'?'selected':''}>＋ Create a new group</option></select><small style="display:block;margin-top:8px">Organize agents your way. You can move them later.</small></div><div class="form-group" id="new-group-field" ${draft.group==='__new'?'':'hidden'}><label for="a-group-name">New group name</label><input id="a-group-name" value="${esc(draft.newGroupName||'')}" placeholder="e.g. My leadership program"></div></form>`:step===2?`<h3>Give it your voice and knowledge</h3><p style="font-size:12px">Choose how your agent communicates, then add the material it should learn from.</p><form id="agent-form" onsubmit="event.preventDefault();advanceAgent()"><div class="form-group"><label for="a-tone">Communication style</label><select id="a-tone">${['Warm & encouraging','Direct & practical','Thoughtful & reflective','Professional & structured'].map(t=>`<option ${draft.tone===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-group"><label>Training content <small>· Optional</small></label><div class="dropzone" role="button" tabindex="0" aria-label="Add training files" onclick="$('#setup-files').click()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();$('#setup-files').click()}" ondragover="event.preventDefault();this.classList.add('drag')" ondragleave="this.classList.remove('drag')" ondrop="event.preventDefault();this.classList.remove('drag');stageSetupFiles(event.dataTransfer.files)"><div class="upload-icon">↥</div><h3>Bring your expertise</h3><p style="font-size:12px;margin:0">Drop your books, guides, or videos here<br>or click to browse</p><small>PDF, DOC, DOCX, TXT, MP4, MOV, AVI · Up to 500 MB each</small></div><input hidden id="setup-files" type="file" multiple accept=".pdf,.doc,.docx,.txt,.mp4,.mov,.avi" onchange="stageSetupFiles(this.files)"><div id="setup-file-list">${setupFileList()}</div><small>You can add more content after creating your agent.</small></div><p class="demo-note">Prototype: saves resource names and details. File content is not uploaded or processed.</p></form>`:`<div style="display:flex;gap:16px;align-items:center;margin-bottom:25px">${glyph(draft.icon)}<div><h2>${esc(draft.name)}</h2><small>${esc(draft.tag)}</small></div></div><h3>Ready to meet your agent?</h3><div class="review-box"><div class="detail-line"><span>Group</span><b>${esc(draft.group==='__new'?draft.newGroupName:db.groups.find(g=>g.id===draft.group)?.name||'Ungrouped')}</b></div><div class="detail-line"><span>Tier</span><b>${draft.tier}</b></div><div class="detail-line"><span>Voice</span><b>${esc(draft.tone)}</b></div><div class="detail-line"><span>Training content</span><b>${(draft.files||[]).length} resources</b></div></div><p style="font-size:12px;margin-top:20px">Next, add your knowledge and try a conversation. This is a browser-local prototype; voice settings are saved for review.</p>`;
modal(`Create new agent <small style="font-size:12px">/ Step ${step} of 3</small>`,body,`<button class="outline" onclick="${step===1?'closeModal()':'readAgentDraft();step--;agentWizard()'}">${step===1?'Cancel':'← Back'}</button><button class="primary" ${step<3?'type="submit" form="agent-form"':'onclick="createAgent()"'}>${step===3?'Create agent ✧':'Next →'}</button>`);$('.modal-head').insertAdjacentHTML('afterend',`<div class="progress-track">${[1,2,3].map(i=>`<i class="${i<=step?'done':''}"></i>`).join('')}</div>`)}
function advanceAgent(){readAgentDraft();if(step===1&&draft.group==='__new'&&!draft.newGroupName){$('#a-group-name').required=true;$('#a-group-name').reportValidity();return}step++;agentWizard()}function createAgent(){if(draft.group==='__new')draft.group=ensureGroup(draft.newGroupName);db.agents.push({...draft,desc:draft.description||draft.tag,favorite:false});(draft.files||[]).forEach(f=>db.files.push({...f,agent:db.agents.length-1}));save();closeModal();openAgent(db.agents.length-1);toast('Your new agent is ready. Add knowledge in Content.')}
function uploadModal(){uploadType='Document';chosenFiles=[];showUpload()}
function showUpload(){modal('Upload training content',`<p style="font-size:12px">Add resources to your agent's knowledge library.</p><div class="tabs" style="width:100%">${['Document','Video','Link'].map(t=>`<button class="${uploadType===t?'selected':''}" onclick="uploadType='${t}';chosenFiles=[];showUpload()">${{Document:'▤',Video:'▹',Link:'↗'}[t]} ${t}</button>`).join('')}</div>${uploadType==='Link'?`<form id="upload-form" onsubmit="event.preventDefault();finishUpload()"><div class="form-group" style="margin-top:24px"><label for="link-title">Resource title *</label><input required id="link-title" placeholder="e.g. My leadership framework"></div><div class="form-group"><label for="link-url">External URL *</label><input required type="url" id="link-url" placeholder="https://"></div></form>`:`<div class="dropzone" tabindex="0" role="button" aria-label="Choose files" onclick="$('#file-input').click()" onkeydown="if(event.key==='Enter')$('#file-input').click()" ondragover="event.preventDefault();this.classList.add('drag')" ondragleave="this.classList.remove('drag')" ondrop="event.preventDefault();this.classList.remove('drag');selectFiles(event.dataTransfer.files)"><div class="upload-icon">↥</div><h3>Drag and drop files here</h3><p style="font-size:12px;margin:0">or click to browse your computer</p><small>${uploadType==='Document'?'PDF, DOC, DOCX, TXT':'MP4, MOV, AVI'} · Maximum 500 MB per file</small></div><input hidden id="file-input" type="file" multiple accept="${uploadType==='Document'?'.pdf,.doc,.docx,.txt':'.mp4,.mov,.avi'}" onchange="selectFiles(this.files)"><div id="file-selection"></div>`}<p class="demo-note">Prototype: saves resource metadata locally. No AI processing.</p>`,`<button class="outline" onclick="closeModal()">Cancel</button><button id="upload-button" class="primary" ${uploadType==='Link'?'type="submit" form="upload-form"':'disabled onclick="finishUpload()"'}>${uploadType==='Link'?'Add link':'Upload files'} ↑</button>`)}
function selectFiles(files){const allow=uploadType==='Document'?/\.(pdf|docx?|txt)$/i:/\.(mp4|mov|avi)$/i;chosenFiles=[...files].filter(f=>f.size<=500*1024*1024&&allow.test(f.name));if(chosenFiles.length!==files.length)toast('Some files were skipped: check file type and 500 MB limit.');$('#file-selection').innerHTML=chosenFiles.map(f=>`<div class="detail-line"><span>▤ ${esc(f.name)}</span><small>${(f.size/1024/1024).toFixed(1)} MB</small></div>`).join('');$('#upload-button').disabled=!chosenFiles.length}
function finishUpload(){if(uploadType==='Link'){db.files.push({name:$('#link-title').value,type:'Link',url:$('#link-url').value,size:'External link',agent:agentId})}else chosenFiles.forEach(f=>db.files.push({name:f.name,type:uploadType,size:(f.size/1024/1024).toFixed(1)+' MB',agent:agentId}));save();closeModal();render();toast('Resource added to the demo library')}
const planData={Starter:{price:29,agents:2,storage:'5 GB',features:['2 AI coaching agents','Up to 100 Q&A pairs','Basic analytics','Email support','5 GB storage']},Professional:{price:99,agents:10,storage:'50 GB',features:['10 AI coaching agents','Unlimited Q&A pairs','Advanced analytics','Priority support','50 GB storage','Custom branding']},Enterprise:{price:299,agents:Infinity,storage:'Unlimited',features:['Unlimited AI agents','Unlimited Q&A pairs','Enterprise analytics','Dedicated support','Unlimited storage','Custom integrations','API access','White-label options']}};
var billingHistoryPage=0;
var billingHistory=Array.from({length:27},(_,i)=>{const date=new Date(2026,10-i,13);return {month:date.toLocaleString('en-US',{month:'long'}),year:date.getFullYear(),n:date.getMonth()+1,plan:i<3?'Professional':'Starter',amount:i<3?99:29}});
function changeBillingHistoryPage(page){billingHistoryPage=Math.max(0,Math.min(Math.ceil(billingHistory.length/6)-1,page));const history=$('#billing-history-content');const x=window.scrollX,y=window.scrollY;history.innerHTML=billingHistoryContent();window.scrollTo(x,y)}
function billing(){let plan=planData[db.plan];return heading('Billing & plans','Manage your subscription, billing, and payment methods.')+`<div class="grid two billing-summary-grid"><section class="card billing-summary-card"><div class="billing-card-heading"><h2>${esc(db.plan)} plan</h2><span class="current-plan-pill">Current</span></div><div class="billing-price">$${(db.billingCycle==='Annual'?plan.price*12:plan.price).toLocaleString()} <small>per ${db.billingCycle==='Annual'?'year':'month'}</small></div><div class="billing-facts"><div class="detail-line"><span>Next billing date</span><b>${db.billingCycle==='Annual'?'November 13, 2027':'December 13, 2026'}</b></div><div class="detail-line"><span>Billing cycle</span><button class="billing-cycle-link" onclick="billingCycleModal()" aria-label="Change billing cycle: ${esc(db.billingCycle||'Monthly')}">${esc(db.billingCycle||'Monthly')}</button></div></div><div class="plan-inclusions"><h3>Included in your plan</h3><ul class="plan-features-columns" style="grid-template-rows:repeat(${Math.ceil(plan.features.length/2)},auto)">${plan.features.map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div><div class="billing-card-action"><button class="outline" onclick="go('plans')">Change plan</button></div></section><section class="card billing-summary-card payment-summary-card"><h2>Payment method</h2><p>Manage your payment details</p><div class="payment-card-stage"><div class="credit-card"><div>${esc(paymentCards()[db.defaultPayment||0].brand)}</div><div class="chip"></div><h2>•••• ${esc(db.last4||'4242')}</h2><div style="display:flex;justify-content:space-between"><small>${esc(paymentCards()[db.defaultPayment||0].name)}</small><small>Exp ${esc(paymentCards()[db.defaultPayment||0].expiry)}</small></div></div></div><div class="billing-card-action"><button class="outline" onclick="paymentModal()">Update payment method</button></div></section></div><div class="card content-list" style="margin-top:24px"><div class="list-title"><h2>Billing history</h2><small>Download invoices and view your payment history</small></div><div id="billing-history-content">${billingHistoryContent()}</div></div><p class="demo-note">Demo billing only. No subscription changes or charges are made.</p>`}
function plans(){const annual=db.billingCycle==='Annual';return `<div class="plan-page-intro"><div><h1>Change plan</h1><p>Choose the plan that fits your practice.</p></div><div class="plan-billing-control"><span>Billed ${annual?'annually':'monthly'}</span><button class="text-button" onclick="billingCycleModal()">Change billing cycle</button></div></div><div class="plan-options reference-plan-options">${Object.entries(planData).map(([name,plan],i)=>{const current=db.plan===name;const over=db.agents.length>plan.agents||(name==='Starter'&&db.qa.length>100);return `<section class="plan-option ${current?'is-current':''}"><div class="plan-title-row"><h2>${name}</h2>${current?'<span class="plan-current-inline">Current plan</span>':''}</div><p class="plan-summary">${['Turn your knowledge into your first coaching experience.','Grow your practice with more agents and your own brand.','Bring your expertise to a larger organization.'][i]}</p><ul class="plan-feature-list">${plan.features.map(feature=>`<li><span aria-hidden="true">✓</span>${esc(feature)}</li>`).join('')}</ul><div class="plan-option-bottom"><div class="plan-option-price"><strong>$${(plan.price*(annual?12:1)).toLocaleString()}</strong><span>per ${annual?'year':'month'}</span></div>${current?'<button class="plan-choice current-plan-choice" onclick="go(&quot;billing&quot;)">Manage</button>':`<button class="plan-choice" onclick="changePlan('${name}')">${plan.price>planData[db.plan].price?'Upgrade to '+name:'Downgrade to '+name}</button>`}</div></section>`}).join('')}</div><div class="plan-help"><div><h3>Need a hand choosing?</h3><p>Find the right fit for the way you work.</p></div><button class="outline" onclick="go('support')">Talk to support</button></div>`}

function changePlan(n){let target=planData[n],over=db.agents.length>target.agents||(n==='Starter'&&db.qa.length>100);modal('Change to '+n,`<p>${over?`Your workspace exceeds this plan's limits. You have ${db.agents.length} agents and ${db.qa.length} Q&A pairs. Reduce usage before switching to ${n}.`:`Switch your demo workspace to ${n} at $${db.billingCycle==='Annual'?target.price*12:target.price}/${db.billingCycle==='Annual'?'year':'month'}?`}</p><div class="review-box">This is a prototype. No payment will be taken and no real subscription will change.</div>`,`<button class="outline" onclick="closeModal()">Cancel</button>${over?'':`<button class="primary" onclick="db.plan='${n}';save();closeModal();go('billing');toast('Demo plan updated to ${n}')">Confirm demo change</button>`}`)}
function paymentCards(){if(!db.paymentCards)db.paymentCards=[{brand:'Visa',last4:db.last4||'4242',name:db.profile.name,expiry:'12/27'}];return db.paymentCards}
function paymentModal(){const cards=paymentCards();modal('Payment methods',`<p>Choose the card used for your subscription.</p><div class="saved-payment-list">${cards.map((card,i)=>`<div class="saved-payment"><div class="payment-brand">${esc(card.brand)}</div><div><strong>${esc(card.brand)} ending in ${esc(card.last4)}</strong><small>Expires ${esc(card.expiry)}</small></div>${i===(db.defaultPayment||0)?'<span class="current-plan-pill">Default</span>':`<button class="text-button" onclick="setDefaultPayment(${i})">Set as default</button>`}</div>`).join('')}</div><button class="outline add-payment" onclick="addPaymentModal()">+ Add new card</button>`,`<button class="primary" onclick="closeModal()">Done</button>`)}
function setDefaultPayment(index){db.defaultPayment=index;db.last4=paymentCards()[index].last4;save();render();paymentModal();toast('Default payment method updated')}
function addPaymentModal(){modal('Add new card',`<form id="payment-form" onsubmit="event.preventDefault();savePaymentCard()"><div class="form-group"><label for="card-name">Name on card</label><input id="card-name" required autocomplete="off" value="${esc(db.profile.name)}"></div><div class="form-group"><label for="card-number">Card number</label><input id="card-number" required inputmode="numeric" pattern="[0-9 ]{13,23}" maxlength="23" placeholder="4242 4242 4242 4242" autocomplete="off" oninput="this.value=this.value.replace(/[^0-9]/g,'').slice(0,19).replace(/(.{4})/g,'$1 ').trim()"></div><div class="payment-input-grid"><div class="form-group"><label for="card-expiry">Expiration date</label><input id="card-expiry" required pattern="(0[1-9]|1[0-2])/[0-9]{2}" maxlength="5" placeholder="MM/YY" autocomplete="off"></div><div class="form-group"><label for="card-cvc">Security code (CVC)</label><input id="card-cvc" type="password" required inputmode="numeric" pattern="[0-9]{3,4}" maxlength="4" placeholder="123" autocomplete="off"><small>3 digits on the back, or 4 on the front for Amex.</small></div></div><label class="payment-default"><input type="checkbox" id="card-default" checked><span>Use as default for future payments</span></label></form>`,`<button class="outline" onclick="paymentModal()">Back</button><button class="primary" type="submit" form="payment-form">Add card</button>`)}

function savePaymentCard(){const number=$('#card-number').value.replace(/[^0-9]/g,'');if(number.length<13||number.length>19){$('#card-number').setCustomValidity('Enter a valid test card number');$('#card-number').reportValidity();return}const cards=paymentCards();cards.push({brand:/^3[47]/.test(number)?'American Express':number.startsWith('5')?'Mastercard':'Visa',last4:number.slice(-4),name:$('#card-name').value.trim(),expiry:$('#card-expiry').value});if($('#card-default').checked){db.defaultPayment=cards.length-1;db.last4=cards[cards.length-1].last4}save();render();paymentModal();toast('Sample card added')}

function downloadFile(name,text,type='text/plain'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadInvoice(month,n,year=2026){const invoice=billingHistory.find(item=>item.n===n&&item.year===year);downloadFile(`Xpertloop-demo-invoice-${year}-${n}.txt`,`XPERTLOOP — DEMO INVOICE\nInvoice: INV-${year}-${String(n).padStart(3,'0')}\nDate: ${month} 13, ${year}\nCustomer: ${db.profile.name}\nPlan: ${invoice.plan}\nAmount: ${invoice.amount}.00\nStatus: Paid\nPaid with: Visa ending in 4242\n\nPrototype sample only. Not a financial document.`);toast('Sample invoice downloaded')}
function metricDetail(i){applyDashboardPeriod();const series=(dashboardPeriod==='current'?[[580,720,890,1050,784,1004],[135,150,165,182,195,193],[2400,3100,3800,4200,4990,5200],[58,62,65,68,67,72]]:[[480,580,720,890,1050,784],[120,135,150,165,182,195],[2100,2400,3100,3800,4200,4990],[55,58,62,65,68,67]])[i];const labels=dashboardPeriod==='current'?['Jun','Jul','Aug','Sep','Oct','Nov']:['May','Jun','Jul','Aug','Sep','Oct'];const max=Math.max(...series),last=series[5],prior=series[4],diff=last-prior,up=diff>=0,percent=Math.abs(diff/prior*100).toFixed(1),format=v=>(i===2?'$':'')+v.toLocaleString()+(i===3?'%':'');modal(stats[i][0],`<div class="metric-detail-summary"><small>${dashboardPeriod==='current'?'November':'October'} 2026</small><div class="number">${format(last)}</div><p class="metric-comparison ${up?'green':'red'}">${up?'↑':'↓'} ${i===3?Math.abs(diff)+' percentage points':percent+'%'} ${up?'increase':'decrease'} from ${labels[4]}${i===3?'':` <span>(${up?'+':'−'}${i===2?'$':''}${Math.abs(diff).toLocaleString()}${i===0?' sessions':i===1?' paying clients':''})</span>`}</p></div>${i===1?`<p class="client-context">55 free · ${last+55} total clients</p>`:''}<div class="metric-chart-heading"><h3>Six-month trend</h3></div><div class="unified-metric-chart" role="img" aria-label="Six-month ${stats[i][0].toLowerCase()} trend with month-over-month change">${series.map((v,j)=>{const d=j?v-series[j-1]:0,positive=d>=0,delta=j?(i===3?Math.abs(d)+' pp':Math.abs(d/series[j-1]*100).toFixed(1)+'%'):'';return `<div class="unified-chart-column"><div class="unified-bar-area"><div tabindex="0" class="unified-bar ${j===5?'is-selected':''}" style="height:${v/max*100}%;--bar-color:${colors[stats[i][4]]}" title="${labels[j]}: ${format(v)}${j?', '+(positive?'increased ':'decreased ')+delta+' from '+labels[j-1]:', first month shown'}"><div class="bar-top-label"><span class="bar-total">${format(v)}</span>${j?`<span class="bar-label-divider" aria-hidden="true">|</span><span class="bar-top-change ${positive?'green':'red'}">${positive?'↑ ':'↓ '}${delta}</span>`:''}</div></div></div><span class="unified-month">${labels[j]}</span></div>`}).join('')}</div>`)}

function studio(){return heading('Content studio','Your expertise. Fresh perspectives. A voice that’s unmistakably yours.',`<span class="badge">✧ ${db.drafts.length} saved drafts</span>`)+`<div class="grid create-layout"><div class="card"><h2>What will you share?</h2><p style="font-size:12px">Start with a topic your audience cares about.</p><form onsubmit="event.preventDefault();generateContent()"><div class="form-group"><label for="studio-agent">Expertise</label><select id="studio-agent">${db.agents.map((a,i)=>`<option value="${i}" ${i===dashAgent?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="form-group"><label for="studio-platform">Platform</label><select id="studio-platform"><option>LinkedIn</option><option>Instagram</option><option>X</option></select></div><div class="form-group"><label for="studio-topic">Topic or audience question</label><textarea class="field" id="studio-topic" rows="4" required placeholder="e.g. Building confidence as a new leader"></textarea></div><button class="primary" style="width:100%" id="generate-button">✧ Generate draft</button></form><p class="demo-note">Template-based demo generation</p></div><div class="card" id="draft-preview">${generated?draftPreview():`<div class="empty" style="padding-top:70px">${glyph(8)}<h2>Your next great idea starts here.</h2><p style="font-size:12px">Turn what you know into something<br>your audience can use.</p><span class="badge">Made for your voice</span></div>`}</div></div>${db.drafts.length?`<div class="section-title"><h2>Saved drafts</h2></div><div class="grid two">${db.drafts.map((d,i)=>`<button class="card" style="text-align:left" onclick="generated=db.drafts[${i}].text;render()"><span class="badge">${esc(d.platform)}</span><h3 style="margin-top:15px">${esc(d.topic)}</h3><small>Open draft →</small></button>`).join('')}</div>`:''}`}
let lastDraftMeta={};function generateContent(){let topic=$('#studio-topic').value.trim(),platform=$('#studio-platform').value,i=Number($('#studio-agent').value);if(!topic)return;lastDraftMeta={topic,platform};let q=db.qa.find(q=>q.agent===i);let idea=q?q.answer:'Start with a clear intention. Choose one small action you can put into practice today, ask for feedback, and build on what you learn.';generated=platform==='X'?`${topic}\n\nOne small step beats a perfect plan.\n\nChoose an action. Ask for feedback. Reflect. Repeat.\n\nWhat will you try today?`:`${topic}: small shifts, meaningful progress.\n\nThe best changes often start with a better question: what could I do differently today?\n\n${idea}\n\nTry this:\n→ Choose one situation to focus on.\n→ Put one principle into practice.\n→ Reflect on what changed, and share what you learned.\n\nWhat's one thing that has worked for you?\n\n#${db.agents[i].name.replace(/[^a-zA-Z]/g,'')} #ProfessionalGrowth`;$('#generate-button').disabled=true;$('#generate-button').innerHTML='Creating your draft <span class="thinking"><i></i><i></i><i></i></span>';setTimeout(()=>{$('#draft-preview').innerHTML=draftPreview();$('#generate-button').disabled=false;$('#generate-button').textContent='✧ Generate another draft'},1000)}
function draftPreview(){return `<div class="page-heading"><h2>Your draft</h2><span class="badge">Ready to make your own</span></div><textarea class="field generated" id="draft-text" rows="15" aria-label="Edit generated draft" oninput="generated=this.value">${esc(generated)}</textarea><div class="card-footer"><button class="outline" onclick="copyDraft()">Copy text</button><button class="primary" onclick="saveDraft()">Save draft</button></div><p class="demo-note">Review and personalize before sharing. This prototype does not publish posts.</p>`}
async function copyDraft(){try{await navigator.clipboard.writeText(generated);toast('Draft copied')}catch{downloadFile('xpertloop-draft.txt',generated);toast('Draft downloaded')}}function saveDraft(){db.drafts.unshift({text:generated,topic:lastDraftMeta.topic||'Untitled draft',platform:lastDraftMeta.platform||'LinkedIn'});save();toast('Draft saved');render()}
function profile(){modal('Your workspace',`<h2>${esc(db.profile.name)}</h2><p>${esc(db.profile.email)}</p><div style="display:grid;gap:8px">${[['profile','◎','Profile settings'],['account','⚙','Account settings'],['notifications','🔔','Notifications'],['usage','▥','Usage'],['billing','▱','Billing & plans'],['support','ⓘ','Help & support']].map(([r,i,t])=>`<button class="outline" style="text-align:left" onclick="closeModal();${r==='notifications'?'notificationsModal()':`go('${r}')`}">${i} &nbsp;${t} <span style="float:right">→</span></button>`).join('')}</div>`,`<button class="text-button red" onclick="signOut()">Sign out of demo →</button>`)}
function signOut(){modal('Sign out of demo',`<p>Your prototype data stays in this browser. Real authentication is not connected.</p>`,`<button class="outline" onclick="closeModal()">Stay here</button><button class="primary" onclick="closeModal();go('dashboard');toast('Demo session restarted')">Restart demo session</button>`)}
function settings(r){if(r==='notifications')return heading('Notifications','Questions clients asked that your agents couldn’t answer.')+`<div class="card"><h2>Unanswered client questions</h2><p style="font-size:12px">Add your response to save it to the agent’s Q&A library and help it answer similar questions in future conversations.</p>${db.pending.map((q,i)=>`<div class="question-row"><div>${esc(q.question)}<small>${esc(db.agents[q.agent].name)} agent couldn’t answer this question</small></div><button class="secondary" onclick="answerQuestion(${i})">Add answer</button></div>`).join('')||'<p>You’re all caught up.</p>'}</div>`;if(r==='support')return heading('How can we help?','A little guidance for your Xpertloop workspace.')+`<div class="grid two">${[['How do I train my agent?','Open an agent and go to Content. Add resources under Files, or share specific answers under Q&A.'],['What happens to unanswered questions?','They appear in Analytics. Click Answer to add your perspective to the agent’s knowledge, then ask the same question in Chat.'],['Does this connect to an AI model?','This prototype uses local sample responses and your saved Q&A. It does not call an AI service.'],['Where is my data saved?','Changes are saved in this browser. Uploaded resources are metadata only. Billing and content generation use demo flows.']].map(([q,a])=>`<details class="card"><summary style="cursor:pointer;font-weight:550">${q}</summary><p style="font-size:12px;margin:15px 0 0">${a}</p></details>`).join('')}</div>`;if(r==='account')return heading('Account settings','Make this workspace work for you.')+`<div class="card" style="max-width:700px"><h2>Demo workspace</h2><p>This prototype saves your edits in your current browser.</p><h3 style="margin-top:30px">Export your workspace</h3><p style="font-size:12px">Download agents, Q&A, resource metadata, and drafts.</p><button class="outline" onclick="downloadFile('xpertloop-workspace.json',JSON.stringify(db,null,2),'application/json');toast('Workspace exported')">↓ Export demo data</button><h3 style="margin-top:35px">Reset demo data</h3><p style="font-size:12px">Restore the original sample workspace.</p><button class="outline red" onclick="resetModal()">Reset workspace</button></div>`;return heading('Profile settings','The person behind the expertise.')+`<form class="card" style="max-width:700px" onsubmit="event.preventDefault();db.profile.name=$('#profile-name').value;db.profile.email=$('#profile-email').value;save();toast('Profile saved')"><div class="avatar" style="width:65px;height:65px;font-size:18px;margin-bottom:28px"><img src="https://images.unsplash.com/photo-1573497019707-1c04de26e58c?auto=format&fit=crop&crop=faces&w=160&h=160&q=85" alt="Emily’s profile photo" width="40" height="40"></div><div class="form-group"><label for="profile-name">Full name</label><input required id="profile-name" value="${esc(db.profile.name)}"></div><div class="form-group"><label for="profile-email">Email address</label><input required type="email" id="profile-email" value="${esc(db.profile.email)}"></div><div class="form-group"><label for="profile-bio">Your expertise</label><textarea class="field" id="profile-bio" rows="4" placeholder="Tell clients about your approach…" oninput="db.profile.bio=this.value">${esc(db.profile.bio||'Executive coach helping leaders build confidence, clarity, and lasting impact.')}</textarea></div><button class="primary">Save changes</button></form>`}
function resetModal(){modal('Reset your workspace?',`<p>This removes your added agents, Q&A, drafts, and resource metadata from this browser and restores the original sample data.</p>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" onclick="db=structuredClone(initial);save();messages={};generated='';closeModal();go('dashboard');toast('Sample workspace restored')">Reset demo data</button>`)}
function animateNumbers(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('[data-count]').forEach(el=>{let raw=el.dataset.count,n=Number(raw.replace(/[^0-9.]/g,'')),start=performance.now();function frame(now){let p=Math.min(1,(now-start)/750),value=Math.round(n*(1-Math.pow(1-p,3)));el.textContent=(raw.startsWith('$')?'$':'')+value.toLocaleString()+(raw.endsWith('%')?'%':'');if(p<1&&el.isConnected)requestAnimationFrame(frame)}requestAnimationFrame(frame)})}

function notificationsModal(){
modal('Notifications',`<h3>Unanswered client questions</h3><p style="font-size:12px">Questions clients asked that your agents couldn’t answer. Add your response to save it to the agent’s Q&A library for future conversations.</p>${db.pending.map((q,i)=>`<div class="question-row"><div>${esc(q.question)}<small>${esc(db.agents[q.agent].name)} agent couldn’t answer this question</small></div><button class="secondary" style="flex-shrink:0" onclick="answerQuestion(${i})">Add answer</button></div>`).join('')||'<div class="empty"><h3>You’re all caught up</h3><p>Your agents have no unanswered client questions.</p></div>'}`,`<button class="outline" onclick="closeModal()">Close</button>`);
}
// User-owned agent organization, exclusive to Expert Loop New.
let groupFilter='all',agentSearch='',agentSort='default',agentStatus='all';
if(!db.groups){db.groups=[{id:'people',name:'People & Culture',color:'#8747ed'},{id:'business',name:'Business & Finance',color:'#00a87d'},{id:'leadership',name:'Leadership Practice',color:'#008ac7'}];db.agents.forEach((a,i)=>a.group=i===1||i===2||i===3?'people':i===4||i===5||i===7||i===8?'business':'leadership');save()}
function ensureGroup(name){const existing=db.groups.find(g=>g.name.toLowerCase()===name.toLowerCase());if(existing)return existing.id;const id='group-'+Date.now().toString(36);db.groups.push({id,name,color:colors[db.groups.length%colors.length]});return id}
function groupPill(id){const g=db.groups.find(g=>g.id===id);return `<span class="group-pill"><i style="background:${g?.color||'#a3acb9'}"></i>${esc(g?.name||'Ungrouped')}</span>`}
function agents(){return heading('Your agents','',`<div style="display:flex;gap:10px"><button class="outline" onclick="groupModal()">＋ New group</button><button class="primary" onclick="newAgent()">＋ Add new agent</button></div>`)+`<div class="group-toolbar"><div class="group-filters"><button class="group-filter ${groupFilter==='all'?'selected':''}" onclick="setGroup('all')">View all <small>${db.agents.length}</small></button>${db.groups.map(g=>`<button class="group-filter ${groupFilter===g.id?'selected':''}" onclick="setGroup('${esc(g.id)}')"><i style="background:${g.color}"></i>${esc(g.name)} <small>(${db.agents.filter(a=>a.group===g.id).length})</small></button>`).join('')}</div><div class="agent-search-row"><input aria-label="Search agents" placeholder="Search agents…" value="${esc(agentSearch)}" oninput="filterAgents(this.value)"><select class="agent-status-filter" aria-label="Filter agents by status" onchange="agentStatus=this.value;refreshAgentResults()"><option value="all" ${agentStatus==='all'?'selected':''}>All statuses</option><option value="active" ${agentStatus==='active'?'selected':''}>Active</option><option value="paused" ${agentStatus==='paused'?'selected':''}>Paused</option></select></div></div><div class="grouped-agent-grid" id="agent-grid">${agentCards()}</div>`}
function setGroup(id){if(groupFilter===id)return;groupFilter=id;const buttons=[...document.querySelectorAll('.group-filter')];buttons.forEach((b,i)=>{const target=i===0?'all':db.groups[i-1]?.id;b.classList.toggle('selected',target===id)});const grid=$('#agent-grid');grid.innerHTML=agentCards();grid.classList.add('filter-results');grid.querySelectorAll('.agent-card').forEach((card,i)=>card.style.setProperty('--reveal-delay',Math.min(i,8)*140+'ms'))}
function filterAgents(v){agentSearch=v;$('#agent-grid').innerHTML=agentCards()}
function agentCards(){const visible=db.agents.map((a,i)=>({...a,id:i})).filter(a=>(a.name+' '+a.desc).toLowerCase().includes(agentSearch.toLowerCase())&&(agentStatus==='all'||(agentStatus==='paused'?!!a.paused:!a.paused))).sort((a,b)=>agentSort==='az'?a.name.localeCompare(b.name):agentSort==='za'?b.name.localeCompare(a.name):agentSort==='newest'?b.id-a.id:a.id-b.id);const sections=groupFilter==='all'?[...db.groups,{id:'ungrouped',name:'Ungrouped',color:'#a3acb9'}]:[db.groups.find(g=>g.id===groupFilter)||{id:'ungrouped',name:'Ungrouped',color:'#a3acb9'}];let result=sections.map(g=>{const list=visible.filter(a=>g.id==='ungrouped'?!db.groups.some(x=>x.id===a.group):a.group===g.id);if(!list.length&&groupFilter==='all')return '';return `<section class="agent-group"><div class="group-heading"><h2><i style="background:${g.color}"></i>${esc(g.name)} <span class="group-count">(${list.length})</span></h2></div><div class="grid two">${list.map(a=>`<article class="card agent-card grouped-card" style="--group-color:${g.color}"><div class="group-card-top">${groupPill(a.group)}<span class="status agent-card-status ${a.paused?'paused':''}">${a.paused?'Paused':'Active'}</span></div><h3>${esc(a.name)}</h3><p>${esc(a.desc||a.tag)}</p><div class="card-footer"><div class="agent-card-actions"><button class="secondary" onclick="openAgent(${a.id})">Open agent →</button>${a.paused?`<button class="resume-agent" onclick="resumeAgent(${a.id})">Resume</button>`:''}</div><button class="compact-move" onclick="moveAgentModal(${a.id})">Move to group <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button></div></article>`).join('')||'<div class="card"><p>No agents in this group yet. Add an agent or move one here.</p></div>'}</div></section>`}).join('');return result||`<div class="card empty"><h3>${agentStatus==='paused'?'No paused agents':'No matching agents'}</h3><p>${agentStatus==='paused'?'All your agents are currently active.':'Try another search or status filter.'}</p></div>`}
function groupModal(id=''){const g=db.groups.find(g=>g.id===id);modal(g?'Edit group':'Create a group',`<p style="font-size:12px">Organize agents by program, topic, audience, or anything that makes sense to you.</p><form id="group-form" onsubmit="event.preventDefault();saveGroup('${id}')"><div class="form-group"><label for="group-name">Group name *</label><input required maxlength="60" id="group-name" value="${esc(g?.name||'')}" placeholder="e.g. My leadership program" oninput="updateGroupMatches('${id}')"></div><div class="existing-groups"><label>Existing groups <small>(${db.groups.length})</small></label><div id="group-matches">${groupMatches('',id)}</div><p id="group-name-feedback" role="status"></p></div><div class="form-group"><label for="group-color">Group color</label><input id="group-color" type="hidden" value="${g?.color||'#008ac7'}"><div class="color-swatches" role="group" aria-label="Group color">${[...new Set(['#008ac7','#8747ed','#00a87d','#eaa126','#e4509b','#64748b',g?.color||'#008ac7'])].map(c=>`<button type="button" class="color-swatch ${c===(g?.color||'#008ac7')?'selected':''}" style="--swatch:${c}" aria-label="${({'#008ac7':'Blue','#8747ed':'Purple','#00a87d':'Green','#eaa126':'Amber','#e4509b':'Pink','#64748b':'Slate'})[c]||'Custom color'}" aria-pressed="${c===(g?.color||'#008ac7')}" onclick="selectGroupColor('${c}',this)"><span>✓</span></button>`).join('')}<button type="button" class="add-color" aria-label="Add custom color" title="Add custom color" onclick="$('#custom-group-color').click()">＋</button><input id="custom-group-color" type="color" value="${g?.color||'#008ac7'}" class="custom-color-input" tabindex="-1" aria-label="Custom group color" onchange="addGroupColor(this.value)"></div></div></form>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" type="submit" id="save-group-button" form="group-form">${g?'Save group':'Create group'}</button>`)}
function saveGroup(id){const name=$('#group-name').value.trim(),color=$('#group-color').value;if(!name)return;const other=db.groups.find(g=>g.name.toLowerCase()===name.toLowerCase()&&g.id!==id);if(other){toast('A group with this name already exists');return}if(id){const g=db.groups.find(g=>g.id===id);g.name=name;g.color=color}else{const created=ensureGroup(name);db.groups.find(g=>g.id===created).color=color}save();closeModal();render();toast(id?'Group updated':'Group created')}
function moveAgentModal(i){const a=db.agents[i];modal('Move agent',`<p>${esc(a.name)}</p><form id="move-form" onsubmit="event.preventDefault();db.agents[${i}].group=$('#move-group').value;save();closeModal();render();toast('Agent moved')"><label for="move-group">Group</label><select id="move-group"><option value="">Ungrouped</option>${db.groups.map(g=>`<option value="${esc(g.id)}" ${a.group===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></form>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" type="submit" form="move-form">Move agent</button>`)}
if(!db.demoPausedExamplesAdded){for(const name of ['Talent & Hiring','Financial Strategy']){const a=db.agents.find(a=>a.name===name);if(a)a.paused=true}db.demoPausedExamplesAdded=true;save()}

if(!db.peopleCultureExamplesAdded){const id=db.agents.findIndex(a=>a.name==='People & Culture');if(id>=0){const files=[{name:'Building a Culture of Trust — Coaching Guide.pdf',type:'Document',size:'2.1 MB'},{name:'Team Values Workshop.pdf',type:'Document',size:'1.4 MB'},{name:'Psychological Safety — Masterclass.mp4',type:'Video',size:'86 MB'},{name:'One-on-One Conversation Templates.docx',type:'Document',size:'640 KB'},{name:'People & Culture Resource Hub',type:'Link',size:'External link',url:'https://example.com/people-culture'}];files.forEach(f=>db.files.push({...f,agent:id}));const qa=[{question:'How can I improve my people & culture skills?',answer:'Start by listening to your team. Use your next one-on-one to ask what helps them do their best work and what gets in the way. Look for a shared theme, choose one improvement together, and follow up in two weeks. Building a better culture comes from small, consistent actions people can see.',category:'Culture Foundations'},{question:'How do I build psychological safety on my team?',answer:'Make it safe to speak up by asking for different perspectives, admitting when you do not have the answer, and thanking people who raise concerns. After a mistake, focus first on what the team can learn. Close the loop by showing how feedback led to action.',category:'Team Trust'},{question:'What should I cover in a one-on-one?',answer:'Start with the person, then discuss priorities, challenges, feedback, and growth. Ask what support would help most. Agree on one or two next steps and revisit them in your next conversation.',category:'People Management'}];qa.forEach(q=>{if(!db.qa.some(x=>x.agent===id&&x.question===q.question))db.qa.push({...q,agent:id})});const pending=[{question:'How do I rebuild trust after a team restructure?',users:4},{question:'How can I include remote teammates in our team culture?',users:3},{question:'How should I address values that are not reflected in daily behavior?',users:2}];pending.forEach(q=>{if(!db.pending.some(x=>x.agent===id&&x.question===q.question))db.pending.push({...q,agent:id})});db.peopleCultureExamplesAdded=true;save()}}

db.pending=db.pending.filter(q=>!db.qa.some(a=>a.agent===q.agent&&a.question.toLowerCase().trim()===q.question.toLowerCase().trim()));save();
if(!db.extendedQuestionExamplesAdded){db.agents.forEach((a,id)=>{const prompts=id===1?['How do I keep culture consistent as our team grows?','How can I address quiet disengagement?','How should I welcome a new team member?','How can I run an inclusive values workshop?','How do I handle culture differences across teams?','How can managers model our values every day?','How should we respond to anonymous feedback?','How can we rebuild connection after a difficult quarter?']:['How can I adapt this approach to a remote team?','How do I handle resistance to change?','How should I set boundaries with stakeholders?','What should I do when an approach stops working?','How can I balance short-term needs and long-term goals?','How do I support someone who feels stuck?','How can I address conflicting expectations?','How do I build a sustainable weekly routine?'];for(const period of ['current','previous']){let n=db.pending.filter(q=>q.agent===id&&(q.period||'current')===period).length;for(const question of prompts){if(n>=8)break;if(db.qa.some(q=>q.agent===id&&q.question===question)||db.pending.some(q=>q.agent===id&&(q.period||'current')===period&&q.question===question))continue;db.pending.push({question,agent:id,period,users:Math.max(1,8-n)});n++}}});db.extendedQuestionExamplesAdded=true;save()}

render();

function selectGroupColor(color,button){$('#group-color').value=color;document.querySelectorAll('.color-swatch').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});button.classList.add('selected');button.setAttribute('aria-pressed','true')}
function addGroupColor(color){const b=document.createElement('button');b.type='button';b.className='color-swatch';b.style.setProperty('--swatch',color);b.setAttribute('aria-label','Custom color');b.innerHTML='<span>✓</span>';b.onclick=()=>selectGroupColor(color,b);$('.add-color').before(b);selectGroupColor(color,b)}

function setupFileList(){return (draft.files||[]).map((f,i)=>`<div class="detail-line" style="gap:12px;align-items:center"><div style="min-width:0;overflow-wrap:anywhere">▤ ${esc(f.name)}<small style="display:block">${f.size} · ${f.type}</small></div><button type="button" class="close" aria-label="Remove ${esc(f.name)}" onclick="draft.files.splice(${i},1);$('#setup-file-list').innerHTML=setupFileList()">×</button></div>`).join('')}
function stageSetupFiles(files){draft.files??=[];let skipped=0;[...files].forEach(f=>{if(f.size>500*1024*1024||! /\.(pdf|docx?|txt|mp4|mov|avi)$/i.test(f.name)){skipped++;return}if(!draft.files.some(x=>x.name===f.name&&x.bytes===f.size))draft.files.push({name:f.name,type:/\.(mp4|mov|avi)$/i.test(f.name)?'Video':'Document',size:(f.size/1024/1024).toFixed(1)+' MB',bytes:f.size})});$('#setup-file-list').innerHTML=setupFileList();if(skipped)toast('Some files were skipped: check file type and 500 MB limit.')}

function moveAgentTo(i,id){db.agents[i].group=id;save();render();toast("Agent moved to "+(db.groups.find(g=>g.id===id)?.name||"Ungrouped"))}

function groupMatches(query,exclude=''){const list=db.groups.filter(g=>g.id!==exclude&&g.name.toLowerCase().includes(query.toLowerCase().trim()));return list.length?list.map(g=>`<span class="existing-group-chip"><i style="background:${g.color}"></i>${esc(g.name)}</span>`).join(''):'<small>No existing groups match this name.</small>'}
function updateGroupMatches(exclude=''){const name=$('#group-name').value.trim();$('#group-matches').innerHTML=groupMatches(name,exclude);const duplicate=db.groups.some(g=>g.id!==exclude&&g.name.toLowerCase()===name.toLowerCase());$('#group-name-feedback').textContent=duplicate?'This group already exists. Choose a different name.':'';$('#save-group-button').disabled=duplicate||!name}

function editAgentModal(){const a=db.agents[agentId];modal('Edit agent',`<form id="edit-agent-form" onsubmit="event.preventDefault();saveAgentEdits()"><div class="form-group"><label for="edit-agent-name">Agent name *</label><input required id="edit-agent-name" value="${esc(a.name)}"></div><div class="form-group"><label for="edit-agent-description">Description *</label><textarea class="field" required rows="3" id="edit-agent-description">${esc(a.description||a.desc||a.tag)}</textarea></div></form><div class="agent-lifecycle"><div><h3>${a.paused?'Resume agent':'Pause agent'}</h3><p>${a.paused?'Make this agent available for conversations again.':'Temporarily stop conversations. Your content and settings stay saved.'}</p></div><button class="outline" onclick="db.agents[agentId].paused=!db.agents[agentId].paused;save();render();editAgentModal()">${a.paused?'Resume':'Pause'}</button></div><div class="agent-lifecycle"><div><h3>Delete agent</h3><p>Remove this agent and its training resources from this demo workspace.</p></div><button class="text-button red" onclick="deleteAgentModal()">Delete</button></div>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" type="submit" form="edit-agent-form">Save changes</button>`)}
function saveAgentEdits(){const a=db.agents[agentId];a.name=$('#edit-agent-name').value.trim();a.description=$('#edit-agent-description').value.trim();if(!a.name||!a.description)return;a.tag=a.description;a.desc=a.description;save();closeModal();render();toast('Agent updated')}
function deleteAgentModal(){modal('Delete agent?',`<p>Delete <b>${esc(db.agents[agentId].name)}</b> and its associated resources, Q&A, and unanswered questions? This cannot be undone.</p>`,`<button class="outline" onclick="editAgentModal()">Cancel</button><button class="primary" style="background:#d84b60" onclick="deleteCurrentAgent()">Delete agent</button>`)}
function deleteCurrentAgent(){const id=agentId;db.agents.splice(id,1);for(const key of ['files','qa','pending'])db[key]=db[key].filter(x=>x.agent!==id).map(x=>({...x,agent:x.agent>id?x.agent-1:x.agent}));messages={};dashAgent=Math.min(dashAgent,Math.max(0,db.agents.length-1));save();closeModal();go('agents');toast('Agent deleted')}

function performanceGlyph(i){if(i===0)return metricGlyph(0);if(i===1)return '<div class="glyph" style="--color:#8747ed;--tint:#eee8ff"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-2-4"/></svg></div>';const body=i===2?'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>':'<circle cx="12" cy="12" r="9"/><path d="M8 14s1 3 4 3 4-3 4-3"/><path d="M8 9h.01M16 9h.01" stroke-width="3"/>';const color=i===2?'#00a87d':'#e38b32',tint=i===2?'#dff8ec':'#fff0dd';return '<div class="glyph" style="--color:'+color+';--tint:'+tint+'"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+body+'</svg></div>'}

let starterAnimating=false;
async function animateStarter(text,button){if(starterAnimating)return;if(db.agents[agentId].paused){toast('This agent is paused. Resume it in Edit agent first.');return}starterAnimating=true;const id=agentId;const input=$('#chat-input'),composer=$('.composer'),send=composer.querySelector('button');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));const starters=[...document.querySelectorAll('.suggestions button')];starters.forEach(b=>b.disabled=true);input.readOnly=true;button.classList.add('starter-chosen');composer.classList.add('starter-filling');input.focus();input.value='';try{if(reduced){input.value=text;await pause(100)}else{const begin=performance.now(),duration=Math.min(1000,Math.max(500,text.length*15));while(input.isConnected&&performance.now()-begin<duration){if(agentId!==id||tab!=='chat')return;const progress=Math.min(1,(performance.now()-begin)/duration);input.value=text.slice(0,Math.ceil(text.length*progress));await pause(20)}input.value=text;await pause(280)}if(!input.isConnected||agentId!==id||tab!=='chat')return;send.classList.add('starter-send');await pause(reduced?0:320);if(input.isConnected&&agentId===id&&tab==='chat')sendChat(text)}finally{starterAnimating=false;input.readOnly=false;starters.forEach(b=>b.disabled=false);composer.classList.remove('starter-filling');send.classList.remove('starter-send');button.classList.remove('starter-chosen')}}

function closeAccountMenu(){document.querySelector('#account-menu')?.remove();document.querySelectorAll('[aria-haspopup="menu"]').forEach(b=>b.setAttribute('aria-expanded','false'))}
function profile(anchor){const trigger=anchor||document.activeElement;if($('#account-menu')){closeAccountMenu();return}closeModal();trigger.setAttribute('aria-expanded','true');const rect=trigger.getBoundingClientRect(),menu=document.createElement('div');menu.id='account-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label','Account menu');menu.innerHTML=`<div class="account-menu-user"><span class="avatar"><img src="https://images.unsplash.com/photo-1573497019707-1c04de26e58c?auto=format&fit=crop&crop=faces&w=160&h=160&q=85" alt="" width="40" height="40"></span><div><b>${esc(db.profile.name)}</b><small>${esc(db.profile.email)}</small></div></div>${[['profile','Profile settings'],['account','Account settings'],['notifications','Notifications'],['usage','Usage'],['billing','Billing & plans'],['support','Help & support']].map(([r,label])=>`<button role="menuitem" onclick="closeAccountMenu();${r==='notifications'?'notificationsModal()':`go('${r}')`}">${label}</button>`).join('')}<button class="account-signout" role="menuitem" onclick="closeAccountMenu();signOut()">Sign out</button>`;document.body.appendChild(menu);const width=Math.min(290,innerWidth-24);menu.style.width=width+'px';menu.style.left=Math.min(Math.max(12,rect.left),innerWidth-width-12)+'px';menu.style.top=Math.min(rect.bottom+9,innerHeight-menu.offsetHeight-12)+'px';menu.querySelector('button')?.focus()}
document.addEventListener('click',e=>{if(!e.target.closest('#account-menu')&&!e.target.closest('[aria-haspopup="menu"]'))closeAccountMenu()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeAccountMenu();const menu=$('#account-menu');if(menu&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const buttons=[...menu.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus()}});window.addEventListener('resize',closeAccountMenu);

function homeActionIcon(i){const body=i===0?'<rect x="5" y="7" width="14" height="13" rx="3"/><path d="M12 3v4M2 12v4m20-4v4M9 16h6"/><circle cx="9" cy="12" r=".75" fill="currentColor"/><circle cx="15" cy="12" r=".75" fill="currentColor"/><circle cx="12" cy="3" r="1" fill="currentColor"/>':'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 12h8M8 16h6"/>';return '<div class="glyph home-action-icon"><svg width="25" height="25" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+body+'</svg></div>'}

function refreshAgentResults(){const grid=$('#agent-grid');grid.innerHTML=agentCards();grid.classList.add('filter-results');grid.querySelectorAll('.agent-card').forEach((card,i)=>card.style.setProperty('--reveal-delay',Math.min(i,8)*140+'ms'))}
function resumeAgent(i){db.agents[i].paused=false;save();refreshAgentResults();toast('Agent resumed and available for conversations')}

function dashboardQuestions(){const a=db.agents[dashAgent];if(!a)return '<div class="card"><h2>Client questions</h2><p>Create an agent to start learning what clients need.</p></div>';const pending=db.pending.filter(q=>q.agent===dashAgent);return `<div class="insights-header"><div><h2>What your clients are asking</h2><p>Spot recurring topics and fill the gaps in your agent’s knowledge.</p></div><div class="insights-agent"><label for="insights-agent">Agent</label><select id="insights-agent" onchange="dashAgent=Number(this.value);$('#dashboard-questions').innerHTML=dashboardQuestions()">${db.agents.map((x,i)=>`<option value="${i}" ${i===dashAgent?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div><div class="grid two insights-grid">${agentQuestionPanels(dashAgent,false)}</div><div class="insights-content-prompt"><div><b>Turn a popular question into your next post.</b><p>Create content inspired by what your clients actually ask.</p></div><button class="outline" onclick="go('create')">Create content →</button></div>`}

function applyDashboardPeriod(){const data=dashboardPeriod==='current'?[['1,004','+220 from last month','↑ 28.12%'],['193','−2 from last month','↓ 1.03%'],['$5,200','+$210 from last month','↑ 4.2%'],['72%','+5 points from last month','↑ 7.46%']]:[['784','−266 from last month','↓ 25.33%'],['195','+13 from last month','↑ 7.14%'],['$4,990','+$790 from last month','↑ 18.81%'],['67%','−1 point from last month','↓ 1.47%']];data.forEach((row,i)=>{stats[i][1]=row[0];stats[i][2]=row[1];stats[i][3]=row[2]})}

function questionAskCount(i){return (dashboardPeriod==='current'?127:113)-i*12}
function agentQuestionPanels(id,full){const month=dashboardPeriod==='current'?'November 2026':'October 2026',limit=full?8:3;const pending=db.pending.filter(q=>q.agent===id&&(q.period||'current')===dashboardPeriod);return `<div class="card insight-panel"><div class="insight-panel-heading"><div><span class="insight-kicker">CONVERSATION TRENDS</span><h3>Most asked questions</h3></div><span class="badge">${month}</span></div><div class="insight-rows">${topQuestions(id).slice(0,limit).map((q,i)=>`<div class="popular-question"><span class="question-rank">${String(i+1).padStart(2,'0')}</span><div class="popular-question-body"><p>${esc(q)}</p><div class="question-frequency"><i style="width:${questionAskCount(i)/questionAskCount(0)*100}%"></i></div></div><span class="question-asks"><b>${questionAskCount(i)}</b><small>asks</small></span></div>`).join('')}</div>${!full?`<div class="insight-panel-footer"><button class="text-button" onclick="viewSelectedAnalytics(${id})">View agent analytics →</button></div>`:''}</div><div class="card insight-panel needs-answers"><div class="insight-panel-heading"><div><span class="insight-kicker">NEEDS YOUR EXPERTISE</span><h3>Waiting for an answer</h3></div><span class="pending-count">${pending.length} pending</span></div><p class="insight-explainer">${month} · Add your perspective to help your agent answer next time.</p><div class="insight-rows">${pending.slice(0,limit).map(q=>`<div class="pending-question"><span class="pending-dot"></span><div><p>${esc(q.question)}</p><small>Asked by ${q.users} ${q.users===1?'client':'clients'}</small></div><button class="answer-question-button" onclick="answerQuestion(${db.pending.indexOf(q)})">Add answer</button></div>`).join('')||'<div class="insight-caught-up"><span>✓</span><h3>You’re all caught up</h3><p>No unanswered questions for this month.</p></div>'}</div>${!full?`<div class="insight-panel-footer"><button class="text-button" onclick="viewSelectedAnalytics(${id})">View all questions →</button></div>`:''}</div>`}
function viewSelectedAnalytics(id){agentId=id;tab='analytics';if(route==='agent-'+id)render();else go('agent-'+id)}

function fileTypeLabel(f){if(f.type==='Link')return 'LINK';const ext=String(f.name||'').match(/\.([a-z0-9]{2,5})$/i)?.[1]?.toUpperCase();if(ext)return esc(ext);const sampleTypes={'Leadership Fundamentals Guide':'PDF','Executive Presence Masterclass':'MP4','Team Building Best Practices':'PDF','Performance Review Templates':'DOCX'};return sampleTypes[f.name]||(f.type==='Video'?'VIDEO':'DOCUMENT')}

function billingCycleModal(){const price=planData[db.plan].price;modal('Change billing cycle',`<p style="font-size:12px">Choose how often you’re billed for your ${esc(db.plan)} plan.</p><form id="cycle-form" onsubmit="event.preventDefault();db.billingCycle=$('#billing-cycle-choice').value;save();closeModal();render();toast('Billing cycle updated in this prototype')"><div class="form-group"><label for="billing-cycle-choice">Billing cycle</label><select id="billing-cycle-choice"><option value="Monthly" ${db.billingCycle!=='Annual'?'selected':''}>Monthly — $${price} per month</option><option value="Annual" ${db.billingCycle==='Annual'?'selected':''}>Annual — $${(price*12).toLocaleString()} per year</option></select></div><p class="demo-note">Prototype only. No payment is taken and no real subscription is changed.</p></form>`,`<button class="outline" onclick="closeModal()">Cancel</button><button class="primary" type="submit" form="cycle-form">Save billing cycle</button>`)}

function togglePlanFeatures(button){const list=$('#additional-plan-features'),open=button.getAttribute('aria-expanded')!=='true';list.hidden=!open;button.setAttribute('aria-expanded',String(open));button.textContent=open?'See less':'See more'}

function usagePage(){const plan=planData[db.plan];return heading('Usage','Track your agents, knowledge, and storage against your plan limits.')+`<div class="card" style="margin-top:24px"><h2>Usage this month</h2><div class="grid" style="grid-template-columns:repeat(3,1fr);margin-top:25px">${[['AI agents used',`${db.agents.length} / ${isFinite(plan.agents)?plan.agents:'∞'}`,Math.min(100,db.agents.length/plan.agents*100)||20],['Q&A pairs',`${db.qa.length} / ${db.plan==='Starter'?'100':'∞'}`,db.plan==='Starter'?db.qa.length:25],['Storage used',`23.4 GB / ${plan.storage}`,47]].map((s,i)=>`<div><div style="display:flex;justify-content:space-between;font-size:11px;gap:5px"><small>${s[0]}</small><b>${s[1]}</b></div><div class="usage-bar" style="--color:${colors[i]}"><i style="width:${s[2]}%"></i></div></div>`).join('')}</div></div><p class="usage-plan-note">Your ${esc(db.plan)} plan sets these limits. <button class="text-button" onclick="go('billing')">View billing &amp; plans</button></p>`}

function billingHistoryContent(){return `<div style="overflow:auto"><table><thead><tr><th>Invoice</th><th>Date</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${billingHistory.slice(billingHistoryPage*6,billingHistoryPage*6+6).map(invoice=>`<tr><td><span class="invoice-description">${invoice.plan} plan · ${invoice.month} ${invoice.year}</span><small class="invoice-reference">INV-${invoice.year}-${String(invoice.n).padStart(3,"0")}</small></td><td>${invoice.month.slice(0,3)} 13, ${invoice.year}</td><td><span class="invoice-amount">$${invoice.amount}.00</span><small class="invoice-payment">Visa ···· 4242</small></td><td><span class="badge green" style="background:#e4fbee">Paid</span></td><td><button class="text-button" onclick="downloadInvoice('${invoice.month}',${invoice.n},${invoice.year})">↓ Download</button></td></tr>`).join("")}</tbody></table></div><div class="invoice-pagination"><span>Showing ${billingHistoryPage*6+1}–${Math.min(billingHistoryPage*6+6,billingHistory.length)} of ${billingHistory.length} invoices</span><nav aria-label="Billing history pages"><button onclick="changeBillingHistoryPage(billingHistoryPage-1)" ${billingHistoryPage===0?"disabled":""}>Previous</button>${Array.from({length:Math.ceil(billingHistory.length/6)},(_,i)=>i).map(page=>`<button class="${page===billingHistoryPage?"selected":""}" aria-label="Page ${page+1}" ${page===billingHistoryPage?'aria-current="page"':""} onclick="changeBillingHistoryPage(${page})">${page+1}</button>`).join("")}<button onclick="changeBillingHistoryPage(billingHistoryPage+1)" ${billingHistoryPage===Math.ceil(billingHistory.length/6)-1?"disabled":""}>Next</button></nav></div>`}
